    return banco.consultar(
        "SELECT id, cliente_id, status, valor, criado_em "
        "FROM pedido ORDER BY criado_em DESC LIMIT %s",
        (limite,),
    )

CREATE TABLE pedido (
  id         SERIAL PRIMARY KEY,
  cliente_id INT NOT NULL REFERENCES cliente(id),
  status     TEXT NOT NULL,
  valor      NUMERIC(12,2) NOT NULL,
  criado_em  TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX idx_pedido_cliente ON pedido (cliente_id);

def montar_relatorio(desde, ate):
    vendas = repositorio.listar_vendas(desde, ate)

    linhas = []
    for venda in vendas:
        vendedor = repositorio.buscar_vendedor(venda["vendedor_id"])
        cliente = repositorio.buscar_cliente(venda["cliente_id"])
        linhas.append({
            "vendedor": vendedor["nome"],
            "cliente": cliente["nome"],
            "valor": venda["valor"],
            "data": venda["criado_em"],
        })

    return linhas

