def importar(caminho):
    total = 0
    with open(caminho, encoding="utf-8") as arquivo:
        for linha in csv.DictReader(arquivo):
            try:
                produto = montar_produto(linha)
                repositorio.salvar(produto)
                total += 1
            except Exception:
                continue
    return {"importados": total}

def montar_produto(linha):
    return {
        "sku": linha["sku"].strip(),
        "nome": linha["nome"].strip(),
        "preco": float(linha["preco"]),
        "estoque": int(linha["estoque"]),
    }

export function calcularTotal(itens, cupom) {
  let total = 0

  for (let i = 0; i <= itens.length; i++) {
    total += itens[i].preco * itens[i].quantidade
  }

  if (total > 200) {
    total = total - total * 0.1
  }

  if (cupom) {
    total = total - cupom.valor
  }

  const frete = total > 300 ? 0 : 25

  return total + frete
}
